def discover_pages(user_token):
    IG = 'id,username,profile_picture_url,followers_count'
    found = {}

    def add(p):
        if p.get('id'):
            found[str(p['id'])] = {**found.get(str(p['id']), {}), **{k: v for k, v in p.items() if v}}

    try:
        r = requests.get(f'{GRAPH_URL}/me/accounts', params={
            'access_token': user_token, 'limit': 100,
            'fields': f'id,name,access_token,picture{{url}},fan_count,instagram_business_account{{{IG}}}',
        }, timeout=30).json()
        for p in r.get('data', []):
            add(p)
    except Exception as e:
        print('[discover] me/accounts:', e)

    try:
        for b in requests.get(f'{GRAPH_URL}/me/businesses',
                              params={'access_token': user_token, 'fields': 'id,name'},
                              timeout=30).json().get('data', []):
            for edge in ('owned_pages', 'client_pages'):
                try:
                    for p in requests.get(f"{GRAPH_URL}/{b['id']}/{edge}",
                                          params={'access_token': user_token,
                                                  'fields': 'id,name,picture{url},fan_count'},
                                          timeout=30).json().get('data', []):
                        add(p)
                except Exception:
                    pass
    except Exception as e:
        print('[discover] businesses:', e)

    for pid, p in list(found.items()):
        if p.get('access_token'):
            continue
        try:
            r = requests.get(f'{GRAPH_URL}/{pid}', params={
                'access_token': user_token,
                'fields': f'access_token,name,picture{{url}},fan_count,instagram_business_account{{{IG}}}',
            }, timeout=20).json()
            if 'error' not in r:
                add({**r, 'id': pid})
        except Exception:
            pass

    return list(found.values())

@app.route("/oauth_callback")
@app.route("/api/oauth/callback")
def oauth_callback():
    if request.args.get('error'):
        return redirect('/?oauth=error&reason=denied')

    code = request.args.get('code')
    if not code:
        return redirect('/?oauth=error&reason=nocode')

    state = request.args.get('state')
    expected_state = request.cookies.get('oauth_state')
    code_verifier = request.cookies.get('oauth_code_verifier')
    
    if not expected_state or not state or state != expected_state:
        print("[OAuth Warning] Mismatched state token")
        return redirect('/?oauth=error&reason=state')

    meta_app_id = os.environ.get('META_APP_ID', '1331918902446123')
    meta_app_secret = os.environ.get('META_APP_SECRET', '')
    
    redirect_uri = "https://metaaimoderator.vercel.app/api/oauth/callback"

    try:
        params = {
            'client_id': meta_app_id,
            'client_secret': meta_app_secret,
            'redirect_uri': redirect_uri,
            'code': code,
        }
        if code_verifier:
            params['code_verifier'] = code_verifier
        short_res = requests.get(f'{GRAPH_URL}/oauth/access_token', params=params, timeout=10).json()

        short = short_res.get('access_token')
        if not short:
            err_msg = short_res.get('error', {}).get('message', 'Token exchange failed')
            print(f"[OAuth Exchange Error] {short_res}")
            return redirect(f'/?oauth=error&reason=token_exchange_failed&details={quote(err_msg)}')

        long_tok_res = requests.get(f'{GRAPH_URL}/oauth/access_token', params={
            'grant_type': 'fb_exchange_token',
            'client_id': meta_app_id,
            'client_secret': meta_app_secret,
            'fb_exchange_token': short,
        }, timeout=10).json()

        long_token = long_tok_res.get('access_token', short)

        session.permanent = True
        session['uid'] = session.get('uid') or os.environ.get("ADMIN_USER", "admin")
        session['authenticated'] = True

        target_client = request.cookies.get('oauth_client_id') or session.get('oauth_client_id') or current_client_id()
        session['oauth_client_id'] = target_client
        session['active_client_id'] = target_client

        try:
            pages = discover_pages(long_token)
            if pages:
                # Auto-link EVERY page the user approved on Facebook's own consent screen â€”
                # no website page-picker. Each page becomes its own client workspace.
                global ACCOUNTS_STORE
                linked = 0
                target_client_obj = next((c for c in AGENCY_CLIENTS_STORE if c.get('id') == target_client), None)
                
                for i, page in enumerate(pages):
                    ptok = page.get('access_token') or long_token
                    pid = str(page.get('id'))
                    if not pid:
                        continue
                    
                    pcid = "client_" + pid
                    if target_client_obj:
                        if target_client_obj.get('page_id') == pid:
                            pcid = target_client
                        elif target_client_obj.get('name') == page.get('name') and not target_client_obj.get('page_id'):
                            pcid = target_client
                        elif len(pages) == 1 and not target_client_obj.get('page_id'):
                            pcid = target_client

                    cobj = next((c for c in AGENCY_CLIENTS_STORE if c.get('id') == pcid), None)
                    if not cobj:
                        cobj = {"id": pcid, "name": page.get('name') or "Ø¹Ù…ÙŠÙ„", "company": page.get('name') or "",
                                "package": "Business VIP", "status": "active", "is_active": True}
                        AGENCY_CLIENTS_STORE.append(cobj)
                    
                    # Only overwrite name if it's a new auto-generated client
                    if pcid != target_client:
                        cobj['name'] = page.get('name') or cobj.get('name')
                        cobj['company'] = page.get('name') or cobj.get('company')
                        
                    cobj['page_id'] = pid
                    cobj['fb_connected'] = True
                    exp = (datetime.now(timezone.utc) + timedelta(days=60)).isoformat()
                    
                    fb_acc = {"id": pid, "name": page.get('name'), "platform": "facebook", "client_id": pcid,
                              "avatar_url": (page.get('picture') or {}).get('data', {}).get('url') if isinstance(page.get('picture'), dict) else None,
                              "access_token": ptok, "access_token_enc": encrypt(ptok),
                              "token_expires_at": exp, "status": "connected", "dm_mode": "auto", "comment_mode": "auto"}
                    
                    ACCOUNTS_STORE = [a for a in ACCOUNTS_STORE if str(a.get('id')) != pid]
                    ACCOUNTS_STORE.append(fb_acc)
                    
                    ig = page.get('instagram_business_account')
                    if ig and ig.get('id'):
                        igid = str(ig['id'])
                        cobj['ig_id'] = igid
                        cobj['ig_connected'] = True
                        
                        unique_ig_id = f"{igid}_{pcid}"
                        ig_acc = {"id": unique_ig_id, "name": ig.get('username') or page.get('name'), "platform": "instagram",
                                  "ig_id": igid, "client_id": pcid, "parent_page_id": pid,
                                  "access_token": ptok, "access_token_enc": encrypt(ptok),
                                  "token_expires_at": exp, "status": "connected", "dm_mode": "auto", "comment_mode": "auto"}
                        
                        ACCOUNTS_STORE = [a for a in ACCOUNTS_STORE if str(a.get('id')) != unique_ig_id]
                        ACCOUNTS_STORE.append(ig_acc)
                    
                    try:
                        requests.post(f"{GRAPH_URL}/{pid}/subscribed_apps",
                                      params={'subscribed_fields': 'messages,messaging_postbacks,feed', 'access_token': ptok}, timeout=8)
                    except Exception:
                        pass
                    linked += 1
                push_setting("meta_ai_accounts", ACCOUNTS_STORE)
                push_setting("meta_ai_clients", AGENCY_CLIENTS_STORE)
                cache["accounts"] = ACCOUNTS_STORE
                cache["clients"] = AGENCY_CLIENTS_STORE
                session.modified = True
                return redirect(f'/?oauth=success&linked={linked}')
        except Exception as ex:
            print(f"[OAuth Auto-Link Error] {ex}")

        return redirect('/?oauth=error&reason=nopages')
    except Exception as e:
        print(f"[OAuth General Error] {e}")
        return redirect('/?oauth=error&reason=exception')

