    if not page:
        return jsonify({'error': 'Ø§Ù„ØµÙØ­Ø© ØºÙŠØ± Ù…ÙˆØ¬ÙˆØ¯Ø©'}), 404

    tok = page.get('access_token') or PAGE_ACCESS_TOKEN
