def drive_file_id(url):
    if not url:
        return ""
    m = re.search(r"/file/d/([A-Za-z0-9_-]+)", url) or re.search(r"[?&]id=([A-Za-z0-9_-]+)", url)
    return m.group(1) if m else ""


def drive_to_direct(url):
    """Ø±Ø§Ø¨Ø· ØªØ­Ù…ÙŠÙ„ Ù…Ø¨Ø§Ø´Ø± Ù…Ù† Google Drive ÙŠÙ‚Ø¯Ø± Meta ÙŠØ³Ø­Ø¨ Ù…Ù†Ù‡ Ø§Ù„Ù…ÙŠØ¯ÙŠØ§ (Ù…Ø¹ confirm Ù„Ù„Ù…Ù„ÙØ§Øª Ø§Ù„ÙƒØ¨ÙŠØ±Ø©)."""
    fid = drive_file_id(url)
    if fid:
        return f"https://drive.google.com/uc?export=download&id={fid}&confirm=t"
    return url or ""


def _resolve_page_token(acc, ig=False):
    """ÙŠØ±Ø¬Ù‘Ø¹ page token Ø­Ù‚ÙŠÙ‚ÙŠ â€” ÙŠØ­ÙˆÙ‘Ù„ Ù…Ù† System User token Ø¹Ø¨Ø± /me/accounts Ù„Ùˆ Ù„Ø²Ù…."""
    tok = PAGE_ACCESS_TOKEN
    if acc.get("access_token_enc"):
        d = decrypt(acc["access_token_enc"])
        if d and len(d) > 20:
            tok = d
    elif acc.get("access_token"):
        tok = acc["access_token"]
    try:
        r = requests.get(f"{GRAPH_URL}/me/accounts?fields=id,access_token&limit=10&access_token={tok}", timeout=10)
        if r.status_code == 200:
            data = r.json().get("data", [])
            if data and data[0].get("access_token"):
                return data[0]["access_token"]
    except Exception:
        pass
    return tok


def publish_scheduled_post(post):
    """ÙŠÙ†Ø´Ø± Ø¨ÙˆØ³Øª/ÙÙŠØ¯ÙŠÙˆ/Ø±ÙŠÙ„Ø² Ù…Ø¬Ø¯ÙˆÙ„ Ø¹Ù„Ù‰ ÙÙŠØ³Ø¨ÙˆÙƒ Ùˆ/Ø£Ùˆ Ø¥Ù†Ø³ØªØ¬Ø±Ø§Ù… Ø¹Ø¨Ø± Graph API. ÙŠØ±Ø¬Ù‘Ø¹ (ok, detail)."""
    media_url = post.get("media_url") or drive_to_direct(post.get("drive_link", ""))
    caption = post.get("caption", "")
    target = post.get("target", "fb")
    media_type = (post.get("media_type") or "image").lower()  # image | video | reel
    is_video = media_type in ("video", "reel")
    results = []

    if target in ("fb", "both"):
        fb = next((a for a in ACCOUNTS_STORE if a.get("platform") == "facebook"), None)
        if fb:
            tok = _resolve_page_token(fb)
            try:
                if is_video and media_url:
                    r = requests.post(f"{GRAPH_URL}/{fb['id']}/videos",
                                      data={"file_url": media_url, "description": caption, "access_token": tok}, timeout=120)
                elif media_url:
                    r = requests.post(f"{GRAPH_URL}/{fb['id']}/photos",
                                      data={"url": media_url, "caption": caption, "access_token": tok}, timeout=60)
                else:
                    r = requests.post(f"{GRAPH_URL}/{fb['id']}/feed",
                                      data={"message": caption, "access_token": tok}, timeout=30)
                results.append(("fb", r.status_code == 200, r.text[:200]))
            except Exception as e:
                results.append(("fb", False, str(e)))

    if target in ("ig", "both"):
        ig = next((a for a in ACCOUNTS_STORE if a.get("platform") == "instagram"), None)
        if ig and media_url:
            ig_id = ig.get("ig_id") or ig.get("id")
            tok = _resolve_page_token(ig, ig=True)
            try:
                if is_video:
                    create_data = {"media_type": "REELS", "video_url": media_url, "caption": caption, "access_token": tok}
                else:
                    create_data = {"image_url": media_url, "caption": caption, "access_token": tok}
                c = requests.post(f"{GRAPH_URL}/{ig_id}/media", data=create_data, timeout=60)
                creation_id = c.json().get("id") if c.status_code == 200 else None
                if creation_id:
                    # video containers need processing time before publish
                    if is_video:
                        for _ in range(10):
                            time.sleep(3)
                            st = requests.get(f"{GRAPH_URL}/{creation_id}?fields=status_code&access_token={tok}", timeout=15)
                            if st.status_code == 200 and st.json().get("status_code") == "FINISHED":
                                break
                    pub = requests.post(f"{GRAPH_URL}/{ig_id}/media_publish",
                                        data={"creation_id": creation_id, "access_token": tok}, timeout=30)
                    results.append(("ig", pub.status_code == 200, pub.text[:200]))
                else:
                    results.append(("ig", False, c.text[:200]))
            except Exception as e:
                results.append(("ig", False, str(e)))

    ok = bool(results) and all(r[1] for r in results)
    return ok, results


@app.route("/api/scheduler", methods=["GET", "POST"])
@auth_guard
def api_scheduler():
    if request.method == "POST":
        data = request.json or {}
        drive_link = data.get("drive_link") or data.get("media_url", "")
        # scheduled_at: Ù…Ù† date (YYYY-MM-DD) + time (HH:MM)Ø› Ù„Ùˆ Ù†Ø§Ù‚Øµ ÙŠØªÙ†Ø´Ø± Ø­Ø§Ù„Ø§Ù‹
        date_s = data.get("date", "")
        time_s = data.get("time", "")
        scheduled_at = None
        if date_s:
            try:
                scheduled_at = datetime.strptime(f"{date_s} {time_s or '00:00'}", "%Y-%m-%d %H:%M").isoformat()
            except Exception:
                scheduled_at = None
        post = {
            "id": f"post-{int(time.time()*1000)}",
            "caption": data.get("caption", ""),
            "target": data.get("target", "fb"),
            "media_type": (data.get("media_type") or "image").lower(),
            "drive_link": drive_link,
            "media_url": drive_to_direct(drive_link),
            "date": date_s,
            "time": time_s,
            "scheduled_at": scheduled_at,
            "status": "pending"
        }
        IN_MEMORY_POSTS.insert(0, post)
        push_setting("meta_ai_scheduled_posts", IN_MEMORY_POSTS)
        return jsonify({"success": True, "post": post})
    return jsonify({"success": True, "scheduled_posts": IN_MEMORY_POSTS})


@app.route("/api/scheduler/<post_id>", methods=["DELETE"])
@auth_guard
def api_scheduler_delete(post_id):
    global IN_MEMORY_POSTS
    before = len(IN_MEMORY_POSTS)
    IN_MEMORY_POSTS = [p for p in IN_MEMORY_POSTS if str(p.get("id")) != str(post_id)]
    push_setting("meta_ai_scheduled_posts", IN_MEMORY_POSTS)
    return jsonify({"success": before != len(IN_MEMORY_POSTS)})














@app.route('/api/cron/process_scheduled', methods=['GET', 'POST'])
def process_scheduled_cron():
    auth_header = request.headers.get('authorization', '')
    cron_secret = os.environ.get('CRON_SECRET', '')
    if cron_secret and auth_header != f"Bearer {cron_secret}":
        return jsonify({"error": "Unauthorized"}), 401

    # Refresh cached settings/pending state from Supabase (no-arg; safe if unconfigured)
    sync_from_supabase()

    # Publish any scheduled posts whose time has come
    now_iso = datetime.now().isoformat()
    published = []
    for post in IN_MEMORY_POSTS:
        if post.get("status") != "pending":
            continue
        sched = post.get("scheduled_at")
        due = (sched is None) or (sched <= now_iso)
        if not due:
            continue
        ok, detail = publish_scheduled_post(post)
        post["status"] = "published" if ok else "failed"
        post["result"] = detail
        published.append({"id": post.get("id"), "ok": ok})
    if published:
        push_setting("meta_ai_scheduled_posts", IN_MEMORY_POSTS)

    return jsonify({
        "status": "processed",
        "pending_count": len(pending_approvals),
        "published": published
    }), 200

